package com.autosphere.controller;
import com.autosphere.config.JwtService;import com.autosphere.model.*;import com.autosphere.repository.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}public record LoginRequest(@Email String email,@NotBlank String password){}@PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest r){var u=users.findByEmail(r.email()).orElse(null);if(u==null||!encoder.matches(r.password(),u.password))return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));return ResponseEntity.ok(Map.of("token",jwt.generate(u.email,u.role.name()),"user",Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role.name())));}}
